; mono.asm -- chapter 23: way 4, monochrome
; generated by gen23.py
        INCLUDE "msx.inc"
        OUTPUT "mono.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
pos     EQU VARS                ; the ball: y, then x
count   EQU VARS + 2            ; the moves left
shift   EQU VARS + 3            ; put's: x AND 7
bptr    EQU VARS + 4            ; put's: the next column of the ball
vptr    EQU VARS + 6            ; wipe's and put's: the column's VRAM address
buf     EQU VARS + $10          ; put's: a column of 16 shapes
; WAY 4: the grass and the ball black on light green, and nothing else.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, scpat
        ld de, $4000
        call fill               ; the scene's shapes
        ld hl, sccol
        ld de, $6000
        call fill               ; and its colours
        ld bc, $1808           ; x, y
        ld (pos), bc
        call put                ; the ball in its first place
        VDP_REG 1, $C0          ; the display on
        in a, (VDP_CTRL)        ; a flag left from before, cleared
        ld a, 64
        ld (count), a
loop:   call frame              ; the end of the paper
m0:     call move
m1:     ld hl, count
        dec (hl)
        jr nz, loop
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret

; move: the ball from where it is to its next place
move:   ld bc, (pos)            ; C = y, B = x: where it is
        call wipe
        ld hl, pos
        inc (hl)
        inc (hl)                ; y: two lines down
        inc hl
        inc (hl)                ; x: a pixel right
        ld bc, (pos)
        jp put

; wipe: the scene back in the ball's three columns at (B, C): its shapes
wipe:   call vaddr
        set 6, h                ; the write bit
        ld (vptr), hl           ; the first column's first byte
        ld a, 3
.col:   push af
        ld de, (vptr)
        ld hl, scpat
        ld l, c                 ; the scene's shapes from line C
        call send
        ld hl, vptr
        ld a, (hl)
        add a, 8
        ld (hl), a              ; the next column: 8 bytes on
        pop af
        dec a
        jr nz, .col
        ret

; put: the ball at (B, C): in each of its three columns its shapes ORed into
; the scene's
put:    ld a, b
        and 7                   ; how far the ball is shifted in its bytes
        ld (shift), a
        add a, a
        ld e, a
        ld d, 0
        ld hl, shifts
        add hl, de
        ld e, (hl)
        inc hl
        ld d, (hl)
        ld (bptr), de           ; its first column: 16 bytes
        call vaddr
        set 6, h
        ld (vptr), hl
        ld a, 3
.col:   push af
        push bc
        ld hl, scpat
        ld l, c                 ; the scene's shapes from line C,
        ld de, (bptr)           ; the ball's column,
        ld bc, buf
        DUP 16
        ld a, (de)
        or (hl)
        ld (bc), a              ; and their OR, into buf
        inc e
        inc l
        inc c
        EDUP
        ld (bptr), de           ; the ball's next column
        pop bc
        ld de, (vptr)
        ld hl, buf
        call send
.next:  ld hl, vptr
        ld a, (hl)
        add a, 8
        ld (hl), a
        pop af
        dec a
        jp nz, .col             ; JP: the loop is too long for JR
        ret

; send: 16 bytes from HL down the screen, from the VRAM address in DE (the
; write bit and the table in D); C: the line of the first. Inside a cell the
; next line is the next byte (chapter 22): the bytes go in runs, one for each
; cell, and between runs the address moves to line 0 of the cell below.
send:   push bc
        ld a, c
        or $F8
        neg                     ; the first run: 8 - (y AND 7), 1 to 8
        ld b, a
        ld a, 16
        sub b                   ; the bytes after it
        ld c, VDP_DATA
.run:   push af
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        out (VDP_CTRL), a       ; the run's address
        otir                    ; its bytes, off the paper (chapter 20)
        inc d                   ; the cell below: 256 bytes on,
        ld a, e
        and $F8
        ld e, a                 ; at its line 0
        pop af
        or a
        jr z, .done             ; no bytes left
        ld b, 8
        cp b
        jr nc, .full
        ld b, a                 ; the last run: what is left
.full:  sub b
        jr .run
.done:  pop bc
        ret

; vaddr: B = x, C = y -> HL = the address of the byte that holds pixel (x, y),
; in the patterns of a Graphic II screen whose names run 0 to 255 in each
; third; add $2000 for its colours. Uses A. (Chapter 22.)
vaddr:  ld a, c
        rrca
        rrca
        rrca
        and $1F                 ; y / 8, the row of characters
        ld h, a
        ld a, b
        and $F8                 ; the column of characters, x 8
        ld l, a
        ld a, c
        and 7                   ; the line in the cell
        or l
        ld l, a
        ret

; fill: the 192 bytes of a scene table, one a line, into all 32 columns of the
; table at the VRAM address in DE (write bit included); the display is off
fill:   ld a, e
        out (VDP_CTRL), a
        ld a, d
        out (VDP_CTRL), a
        ld c, VDP_DATA
        ld d, 24                ; 24 rows of cells
.row:   ld e, 32                ; of 32 cells
.cell:  push hl
        ld b, 8
        otir                    ; a cell's eight lines
        pop hl
        dec e
        jr nz, .cell
        ld a, l
        add a, 8
        ld l, a                 ; the next row's lines (L = y)
        dec d
        jr nz, .row
        ret

; the scene: for every line of the screen a byte of shape and a byte of colour,
; the same in every column; each table a page of its own, so that L = y
        ALIGN 256
scpat:
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        ALIGN 256
sccol:
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        ALIGN 256               ; no column of the ball crosses a page
shifts: dw ball0, ball1, ball2, ball3, ball4, ball5, ball6, ball7
ball0:                          ; shifted 0: three columns of 16
        db $03, $0F, $1F, $3F, $7F, $7F, $FF, $FF, $FF, $FF, $7F, $7F, $3F, $1F, $0F, $03
        db $C0, $F0, $F8, $FC, $FE, $FE, $FF, $FF, $FF, $FF, $FE, $FE, $FC, $F8, $F0, $C0
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
ball1:                          ; shifted 1: three columns of 16
        db $01, $07, $0F, $1F, $3F, $3F, $7F, $7F, $7F, $7F, $3F, $3F, $1F, $0F, $07, $01
        db $E0, $F8, $FC, $FE, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FE, $FC, $F8, $E0
        db $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $00, $00, $00, $00, $00, $00
ball2:                          ; shifted 2: three columns of 16
        db $00, $03, $07, $0F, $1F, $1F, $3F, $3F, $3F, $3F, $1F, $1F, $0F, $07, $03, $00
        db $F0, $FC, $FE, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FE, $FC, $F0
        db $00, $00, $00, $00, $80, $80, $C0, $C0, $C0, $C0, $80, $80, $00, $00, $00, $00
ball3:                          ; shifted 3: three columns of 16
        db $00, $01, $03, $07, $0F, $0F, $1F, $1F, $1F, $1F, $0F, $0F, $07, $03, $01, $00
        db $78, $FE, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FE, $78
        db $00, $00, $00, $80, $C0, $C0, $E0, $E0, $E0, $E0, $C0, $C0, $80, $00, $00, $00
ball4:                          ; shifted 4: three columns of 16
        db $00, $00, $01, $03, $07, $07, $0F, $0F, $0F, $0F, $07, $07, $03, $01, $00, $00
        db $3C, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $3C
        db $00, $00, $80, $C0, $E0, $E0, $F0, $F0, $F0, $F0, $E0, $E0, $C0, $80, $00, $00
ball5:                          ; shifted 5: three columns of 16
        db $00, $00, $00, $01, $03, $03, $07, $07, $07, $07, $03, $03, $01, $00, $00, $00
        db $1E, $7F, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $7F, $1E
        db $00, $80, $C0, $E0, $F0, $F0, $F8, $F8, $F8, $F8, $F0, $F0, $E0, $C0, $80, $00
ball6:                          ; shifted 6: three columns of 16
        db $00, $00, $00, $00, $01, $01, $03, $03, $03, $03, $01, $01, $00, $00, $00, $00
        db $0F, $3F, $7F, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $7F, $3F, $0F
        db $00, $C0, $E0, $F0, $F8, $F8, $FC, $FC, $FC, $FC, $F8, $F8, $F0, $E0, $C0, $00
ball7:                          ; shifted 7: three columns of 16
        db $00, $00, $00, $00, $00, $00, $01, $01, $01, $01, $00, $00, $00, $00, $00, $00
        db $07, $1F, $3F, $7F, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $7F, $3F, $1F, $07
        db $80, $E0, $F0, $F8, $FC, $FC, $FE, $FE, $FE, $FE, $FC, $FC, $F8, $F0, $E0, $80
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
